/** Source-grounded human-review metrics. Not association TP/FP/FN or LLM judge output. */
export type ClaimVerdict = 'unrated' | 'supported' | 'contradicted' | 'not_in_source' | 'uncertain'
export type ClaimReview = { id: string; text: string; verdict: ClaimVerdict; evidence: string;
  reason: string; confidence?: number | null; matched_fact_ids?: string[] }
export type FactGrade = 'unrated' | 'covered' | 'partial' | 'missing' | 'incorrect' | 'na'
export type AtomicReview = { grades?: Record<string, FactGrade>; claims?: ClaimReview[] }
export type GoldFact = { id: string; expectation: string }
export type SummaryMetrics = {
  status: 'scored' | 'needs_gold_facts' | 'needs_candidate_claims' | 'unresolved' | 'invalid';
  precision: number | null; recall: number | null; f1_style: number | null;
  supported: number; claim_count: number; covered: number; fact_count: number;
  unsupported: number; contradicted: number; missing: number; reason: string;
}
export function scoreSummaryFacts(facts: GoldFact[], review?: AtomicReview): SummaryMetrics {
  const claims = review?.claims || []
  const base = { precision: null, recall: null, f1_style: null, supported: 0, claim_count: claims.length,
    covered: 0, fact_count: facts.length, unsupported: 0, contradicted: 0, missing: 0 }
  const fail = (status: SummaryMetrics['status'], reason: string): SummaryMetrics => ({ ...base, status, reason })
  if (!facts.length) return fail('needs_gold_facts', 'Freeze atomic important facts in Gold Review; a reference prose summary alone has no recall denominator.')
  if (!claims.length) return fail('needs_candidate_claims', 'Extract and human-review distinct candidate summary claims; there is no precision denominator yet.')
  if (new Set(facts.map(f => f.id)).size !== facts.length || new Set(claims.map(c => c.id)).size !== claims.length ||
      facts.some(f => !f.id.trim() || !f.expectation.trim()) || claims.some(c => !c.text.trim())) {
    return fail('invalid', 'Duplicate/blank source fact or summary claim. Deduplicate semantically before scoring.')
  }
  const grades = facts.map(f => review?.grades?.[f.id] || 'unrated')
  if (grades.some(g => !['covered','missing','incorrect'].includes(g))) {
    return fail('unresolved', 'Review every frozen important fact; split partial facts; N/A and uncertain judgments cannot be silently scored.')
  }
  if (claims.some(c => !['supported','contradicted','not_in_source'].includes(c.verdict) ||
    (c.verdict === 'supported' && !c.evidence.trim()) ||
    (c.verdict !== 'supported' && !c.reason.trim()) ||
    (c.confidence !== undefined && c.confidence !== null && (!Number.isFinite(c.confidence) || c.confidence < 0 || c.confidence > 1)))) {
    return fail('unresolved', 'Resolve claim verdicts and record evidence for supported claims / reasons for rejected claims.')
  }
  const supported = claims.filter(c => c.verdict === 'supported').length
  const covered = grades.filter(g => g === 'covered').length
  const precision = supported / claims.length
  const recall = covered / facts.length
  return { status: 'scored', precision, recall, f1_style: precision + recall === 0 ? 0 : 2 * precision * recall / (precision + recall),
    supported, claim_count: claims.length, covered, fact_count: facts.length,
    unsupported: claims.filter(c => c.verdict === 'not_in_source').length,
    contradicted: claims.filter(c => c.verdict === 'contradicted').length,
    missing: facts.length - covered,
    reason: 'Human-reviewed source-grounded atomic claims and frozen important facts. This is F1-style, not classical decision F1.' }
}
export function aggregateSummaryMetrics(items: SummaryMetrics[]): SummaryMetrics {
  if (!items.length) return scoreSummaryFacts([], undefined)
  const incomplete = items.find(m => m.status !== 'scored')
  if (incomplete) return { ...incomplete, precision: null, recall: null, f1_style: null,
    reason: `At least one attempt is unscored: ${incomplete.reason}` }
  const supported = items.reduce((n, m) => n + m.supported, 0)
  const claim_count = items.reduce((n, m) => n + m.claim_count, 0)
  const covered = items.reduce((n, m) => n + m.covered, 0)
  const fact_count = items.reduce((n, m) => n + m.fact_count, 0)
  const precision = supported / claim_count
  const recall = covered / fact_count
  return { status: 'scored', precision, recall, f1_style: precision + recall === 0 ? 0 : 2 * precision * recall / (precision + recall),
    supported, claim_count, covered, fact_count,
    unsupported: items.reduce((n, m) => n + m.unsupported, 0),
    contradicted: items.reduce((n, m) => n + m.contradicted, 0),
    missing: items.reduce((n, m) => n + m.missing, 0),
    reason: 'Micro-aggregated independently reviewed source facts and candidate claims across completed attempts.' }
}
