'use client'

import { ClaimReview, SummaryMetrics, scoreSummaryFacts } from './factual-metrics'
import { SummaryFactNetwork } from './summary-fact-network'

import React, { useCallback, useEffect, useMemo, useState } from 'react'
import { Alert, Badge, Button, Card, Form, Spinner, Table } from 'react-bootstrap'

type Source = { alias: string; title: string; sha256?: string }
type Criterion = { id: string; expectation: string }
type GoldDecision = 'include' | 'exclude'
type Gold = { source_alias: string; revision: string; saved_at?: string; criteria: Criterion[];
  gold_summary?: string; gold_note_alias?: string | null; gold_summary_sha256?: string | null }
type Grade = 'unrated' | 'covered' | 'partial' | 'missing' | 'incorrect' | 'na'
type Review = { grades: Record<string, Grade>; summary_grades?: Record<string, Grade>; claims?: ClaimReview[]; notes?: string; reviewed_at?: string }
type Provisional = { status: 'ready' | 'queued' | 'running' | 'failed' | 'not_started';
  run_id?: string; alias?: string; role?: string; test?: string; stage?: string; error?: string;
  judge_model?: string; judge_kind?: string; grades?: Record<string, Grade>; claims?: ClaimReview[];
  fact_reasons?: Record<string, string>; uncertain?: number; scores?: {
    status: string; precision?: number; recall?: number; f1_style?: number; reason?: string } }
type Attempt = { name: string; source_alias: string; source_title: string; model_role?: string; model?: string; status: string;
  output?: string; finish_reason?: string; truncated?: boolean; duration_seconds?: number; error?: string;
  score?: { coverage_proxy: number; coverage_total: number; missing_proxy: string[]; alerts: string[] } }
type Report = { id?: string; status?: string; model?: string; providers?: Record<string, { model: string }>;
  sources?: Source[]; gold?: Record<string, Gold | null>; attempts?: Attempt[]; reviews?: Record<string, Review>; error?: string; state?: string }
type ReviewStats = { reviewed: number; applicable: number; possible: number; covered: number; incorrect: number; missing: number }
type ShortRun = { id: string; status: string; started_at?: string; model?: string; roles?: string[];
  attempts: number; role_attempts?: Record<string, number>; role_seconds?: Record<string, number>;
  source_titles?: string[]; providers?: Record<string, { model: string }>; reviews?: Record<string, ReviewStats>;
  factual_metrics?: Record<string, (SummaryMetrics & { completed_attempts: number; total_attempts: number }) | null> }
const API = '/memex-wiki-summary-quality-benchmarks/api'
const FIXTURE = 'fixture-64-PAS-9980'
const MAX = 3
const TESTS = ['A-baseline', 'B-complete', 'C-repeat-1', 'C-repeat-2', 'C-repeat-3']
const LABELS: { value: Grade; label: string }[] = [
  { value: 'unrated', label: 'Not rated' }, { value: 'covered', label: 'Covered accurately' },
  { value: 'partial', label: 'Partially covered' }, { value: 'missing', label: 'Missing' },
  { value: 'incorrect', label: 'Incorrect / contradicted' }, { value: 'na', label: 'Not applicable' },
]
const SUMMARY_DIMENSIONS = [
  { id: 'completeness', label: 'Completeness of substantive themes' },
  { id: 'accuracy', label: 'Factual correctness and terminology' },
  { id: 'qualifications', label: 'Conditions, limitations and normative force' },
  { id: 'grounding', label: 'No invented or unsupported claims' },
] as const
const PAS_GOLD: Criterion[] = [
  { id: '14-format', expectation: 'No prescribed format or pro-forma; report should be factual and establish inherently low risk.' },
  { id: '14-1', expectation: 'Report should clarify it informs the building fire risk assessment (FRA) in the Fire Safety Order context.' },
  { id: '14-2', expectation: 'Report should not claim compliance with building regulations, now or when constructed.' },
  { id: '14-3', expectation: 'Where a building or all its external walls are determined inherently low risk under Clause 4 using the Figure 1 process, the report should include a statement of signatory competence.' },
  { id: '14-4a', expectation: 'Minimum report information: appraiser name and organisation.' },
  { id: '14-4b', expectation: 'Minimum report information: report completion and building inspection dates.' },
  { id: '14-4c', expectation: 'Minimum report information: building address.' },
  { id: '14-4d', expectation: 'Minimum report information: building use or uses.' },
  { id: '14-4e', expectation: 'Minimum report information: building dimensions.' },
  { id: '14-4f', expectation: 'Minimum report information: approximate building age.' },
  { id: '14-4g', expectation: 'Minimum report information: how low risk was established.' },
  { id: '14-4h', expectation: 'Minimum report information: assistance for dutyholders statutory obligations.' },
  { id: 'normative', expectation: 'Do not strengthen SHOULD to MUST; preserve conditional scope and statutory distinctions.' },
]
function percent(n: number, total: number) { return total ? `${(100 * n / total).toFixed(1)}%` : 'Not reviewed' }
function keyFor(alias: string, role: string, name: string) { return `${alias}::${role}::${name}` }
function humanGradeSummary(review: Review | undefined, gold: Gold | null | undefined, attemptStatus: string) {
  const dimensions: Record<string, string> = {
    completeness: 'Completeness', accuracy: 'Accuracy', qualifications: 'Conditions', grounding: 'Grounding',
  }
  if (attemptStatus === 'failed') return { coverage: '—', outcome: 'Failed', reason: 'Model call failed' }
  if (attemptStatus === 'running') return { coverage: '—', outcome: 'Running', reason: 'Awaiting model output' }
  if (!gold) return { coverage: '—', outcome: 'No Gold', reason: 'No Gold Set frozen in this run' }
  const referenceCount = (gold.gold_summary ? 4 : 0) + (gold.criteria?.length || 0)
  if (!review) return { coverage: '—', outcome: attemptStatus === 'truncated' ? 'Truncated · unreviewed' : 'Unreviewed', reason: 'Human assessment not saved' }
  const rows = [
    ...(gold.gold_summary ? Object.entries(dimensions).map(([id, label]) => [label, review.summary_grades?.[id] || 'unrated']) : []),
    ...(gold.criteria || []).map((item) => [item.id, review.grades?.[item.id] || 'unrated']),
  ]
  const rated = rows.filter(([, grade]) => grade !== 'unrated' && grade !== 'na')
  const covered = rated.reduce((sum, [, grade]) => sum + (grade === 'covered' ? 1 : grade === 'partial' ? 0.5 : 0), 0)
  const problem = rows.filter(([, grade]) => ['incorrect', 'missing', 'partial'].includes(grade))
  const error = problem.filter(([, grade]) => grade === 'incorrect')
  const missing = problem.filter(([, grade]) => grade === 'missing')
  const partial = problem.filter(([, grade]) => grade === 'partial')
  let outcome = error.length ? 'Incorrect' : missing.length ? 'Missing' : partial.length ? 'Partial' :
    rated.length < referenceCount ? 'Review incomplete' : 'Covered'
  if (!rated.length) outcome = 'Unreviewed'
  if (attemptStatus === 'truncated') outcome += ' · truncated'
  const reason = [problem.map(([name, grade]) => `${name}: ${grade}`).join('; '), review.notes?.trim()].filter(Boolean).join(' — ') ||
    (rated.length < referenceCount ? 'Some Gold dimensions have not been graded' : 'Human-reviewed')
  return { coverage: rated.length ? `${percent(covered, rated.length)} (${rated.length}/${referenceCount} graded)` : '—',
    outcome, reason }
}

export function MemexWikiSummaryQualityBenchmarks() {
  const [sources, setSources] = useState<Source[]>([])
  const [query, setQuery] = useState('')
  const [chosen, setChosen] = useState<string[]>([])
  const [sourceLoading, setSourceLoading] = useState(true)
  const [maxTokens, setMaxTokens] = useState(4096)
  const [mode, setMode] = useState<'local' | 'frontier' | 'both'>('local')
  const [frontier, setFrontier] = useState<{ available: boolean; model: string | null }>({ available: false, model: null })
  const [externalConsent, setExternalConsent] = useState(false)
  const [goldAlias, setGoldAlias] = useState(FIXTURE)
  const [gold, setGold] = useState<Criterion[]>([])
  // Decisions are LOCAL DRAFTS. Only human-approved 'include' facts are saved.
  // Existing saved criteria load as included to preserve previously approved Gold Sets.
  const [goldDecisions, setGoldDecisions] = useState<Record<string, GoldDecision>>({})
  const [goldWizardIndex, setGoldWizardIndex] = useState(0)
  const [goldPendingOnly, setGoldPendingOnly] = useState(false)
  const [goldSummary, setGoldSummary] = useState('')
  const [goldNoteAlias, setGoldNoteAlias] = useState('')
  const [goldNoteQuery, setGoldNoteQuery] = useState('memex-gold-summary-pas9980-clause14-page48')
  const [goldNoteLoading, setGoldNoteLoading] = useState(false)
  const [goldRevision, setGoldRevision] = useState('')
  const [goldDirty, setGoldDirty] = useState(false)
  const [goldSaving, setGoldSaving] = useState(false)
  const [runs, setRuns] = useState<ShortRun[]>([])
  const [ledgerModel, setLedgerModel] = useState<'all' | 'local' | 'frontier'>('all')
  const [resultOutcome, setResultOutcome] = useState('all')
  const [selected, setSelected] = useState('')
  const [report, setReport] = useState<Report>()
  const [attemptName, setAttemptName] = useState('B-complete')
  const [comparisonAlias, setComparisonAlias] = useState('')
  const [reviewRole, setReviewRole] = useState('local')
  const [draftGrades, setDraftGrades] = useState<Record<string, Grade>>({})
  const [summaryGrades, setSummaryGrades] = useState<Record<string, Grade>>({})
  const [reviewNotes, setReviewNotes] = useState('')
  const [candidateClaims, setCandidateClaims] = useState<ClaimReview[]>([])
  const [savingReview, setSavingReview] = useState(false)
  const [provisional, setProvisional] = useState<Provisional>({ status: 'not_started' })
  const [provisionalFor, setProvisionalFor] = useState('')
  const [evaluating, setEvaluating] = useState(false)
  const [starting, setStarting] = useState(false)
  const [error, setError] = useState('')
  const [notice, setNotice] = useState('')

  const getJSON = useCallback(async (url: string) => {
    const response = await fetch(url, { cache: 'no-store' })
    const data = await response.json()
    if (!response.ok) throw new Error(data.error || `HTTP ${response.status}`)
    return data
  }, [])
  const postJSON = useCallback(async (url: string, payload: unknown) => {
    const response = await fetch(url, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload) })
    const data = await response.json()
    if (!response.ok) throw new Error(data.error || `HTTP ${response.status}`)
    return data
  }, [])
  const loadSources = useCallback(async () => {
    setSourceLoading(true)
    try { setSources((await getJSON(`${API}?sources=1`)).sources || []) }
    catch (e) { setError(String(e)) }
    finally { setSourceLoading(false) }
  }, [getJSON])
  const loadLedger = useCallback(async () => {
    try { const data = await getJSON(API); setRuns(data.runs || []); setFrontier(data.frontier || { available: false, model: null }) }
    catch (e) { setError(String(e)) }
  }, [getJSON])
  const loadRun = useCallback(async (id: string) => {
    try { setReport(await getJSON(`${API}?runId=${encodeURIComponent(id)}`)) }
    catch (e) { setError(String(e)) }
  }, [getJSON])
  useEffect(() => { void loadSources(); void loadLedger() }, [loadSources, loadLedger])
  useEffect(() => {
    const aliases = chosen.length ? chosen : [FIXTURE]
    if (!aliases.includes(goldAlias)) setGoldAlias(aliases[0])
  }, [chosen, goldAlias])
  useEffect(() => {
    let valid = true
    setGold([]); setGoldDecisions({}); setGoldWizardIndex(0); setGoldSummary(''); setGoldNoteAlias(''); setGoldRevision(''); setGoldDirty(false)
    void getJSON(`${API}/gold?alias=${encodeURIComponent(goldAlias)}`).then((data) => {
      if (!valid) return
      const criteria = (data.gold?.criteria || []) as Criterion[]
      setGold(criteria)
      setGoldDecisions(Object.fromEntries(criteria.map((c) => [c.id, 'include' as GoldDecision])))
      setGoldWizardIndex(0)
      setGoldSummary(data.gold?.gold_summary || '')
      setGoldNoteAlias(data.gold?.gold_note_alias || ''); setGoldRevision(data.gold?.revision || '')
    }).catch((e) => { if (valid) setError(String(e)) })
    return () => { valid = false }
  }, [goldAlias, getJSON])
  useEffect(() => {
    if (!selected) return
    void loadRun(selected)
    const timer = window.setInterval(() => { if (!report || report.status === 'running' || report.state === 'starting') void loadRun(selected) }, 6500)
    return () => window.clearInterval(timer)
  }, [selected, loadRun, report?.status, report?.state])
  useEffect(() => {
    if (!report?.sources?.length) return
    if (!report.sources.some((s) => s.alias === comparisonAlias)) setComparisonAlias(report.sources[0].alias)
  }, [report, comparisonAlias])
  const visibleSources = useMemo(() => sources.filter((s) =>
    `${s.title} ${s.alias}`.toLowerCase().includes(query.trim().toLowerCase())).slice(0, 60), [sources, query])
  const aliases = chosen.length ? chosen : [FIXTURE]
  const toggle = (alias: string) => setChosen((current) => current.includes(alias) ? current.filter((x) => x !== alias)
    : current.length < MAX ? [...current, alias] : current)
  const selectedRun = runs.find((r) => r.id === selected)
  const goldForReview = report?.gold?.[comparisonAlias]?.criteria || []
  const summaryForReview = report?.gold?.[comparisonAlias]?.gold_summary || ''
  const reviewKey = keyFor(comparisonAlias, reviewRole, attemptName)
  const savedReview = report?.reviews?.[reviewKey]
  const evalKey = `${selected}::${reviewKey}`
  const activeProvisional = provisionalFor === evalKey && provisional.status === 'ready' ? provisional : undefined
  const tableReview: Review | undefined = savedReview || (activeProvisional?.grades && activeProvisional?.claims
    ? { grades: activeProvisional.grades, claims: activeProvisional.claims } : undefined)
  const provisionalOnly = !savedReview && !!activeProvisional
  useEffect(() => {
    setDraftGrades(savedReview?.grades || {})
    setSummaryGrades(savedReview?.summary_grades || {})
    setReviewNotes(savedReview?.notes || '')
    setCandidateClaims(savedReview?.claims || [])
  }, [reviewKey, savedReview])
  const compared = (role: string) => report?.attempts?.find((a) => a.source_alias === comparisonAlias &&
    (a.model_role || 'local') === role && a.name === attemptName)
  const evalUrl = useCallback(() => `${API}/evaluate?runId=${encodeURIComponent(selected)}&alias=${encodeURIComponent(comparisonAlias)}` +
    `&role=${encodeURIComponent(reviewRole)}&name=${encodeURIComponent(attemptName)}`, [selected, comparisonAlias, reviewRole, attemptName])
  useEffect(() => {
    if (!selected || !comparisonAlias || !report?.gold?.[comparisonAlias]) return
    const key = `${selected}::${keyFor(comparisonAlias, reviewRole, attemptName)}`
    let live = true
    const refresh = async () => {
      try {
        const value = await getJSON(evalUrl()) as Provisional
        if (live) { setProvisional(value); setProvisionalFor(key) }
      } catch (e) { if (live) setError(String(e)) }
    }
    void refresh()
    const timer = window.setInterval(refresh, 6500)
    return () => { live = false; window.clearInterval(timer) }
  }, [selected, comparisonAlias, reviewRole, attemptName, report?.gold, getJSON, evalUrl])
  const evaluateSaved = async () => {
    setEvaluating(true); setError(''); setNotice('')
    try {
      const row = await postJSON(`${API}/evaluate`, { runId: selected, alias: comparisonAlias, role: reviewRole, name: attemptName }) as Provisional
      setProvisional(row); setProvisionalFor(evalKey)
      setNotice('Provisional evaluation queued for SAVED model output. Human review records remain untouched.')
    } catch (e) { setError(String(e)) }
    finally { setEvaluating(false) }
  }
  const draftFromProposal = () => {
    if (!activeProvisional?.grades) return
    if (savedReview && !window.confirm('Replace locally edited review fields with provisional suggestions? Saved review is NOT changed until you click Save.')) return
    setDraftGrades({ ...activeProvisional.grades })
    // Association-style direct Gold decisions do not fabricate candidate claims.
    setCandidateClaims((activeProvisional.claims || []).map(c => ({ ...c })))
    setNotice('Provisional Gold decisions copied into editable draft. Verify each against the ORIGINAL source and saved summary before saving.')
  }
  const loadGoldFromNote = async () => {
    setGoldNoteLoading(true); setError(''); setNotice('')
    try {
      const data = await getJSON(`${API}/gold/import?noteAlias=${encodeURIComponent(goldNoteQuery.trim())}`)
      setGoldSummary(data.summary); setGoldNoteAlias(data.noteAlias); setGoldDirty(true)
      setNotice(`Imported HedgeDoc Gold note ${data.noteAlias}. Verify against original source and click Save Gold Set to approve.`)
    } catch (e) { setError(String(e)) }
    finally { setGoldNoteLoading(false) }
  }
  const saveGold = async () => {
    setGoldSaving(true); setError(''); setNotice('')
    try {
      if (gold.some((c) => !goldDecisions[c.id])) {
        throw new Error('Review every draft source fact using Include / Exclude before saving the Gold Set.')
      }
      const approvedFacts = gold.filter((c) => goldDecisions[c.id] === 'include')
      if (!approvedFacts.length && (gold.length > 0 || goldSummary.trim().length < 200)) {
        throw new Error('Include an important source fact, or use a prose-only Gold Set without draft facts (no P/R/F1).')
      }
      const result = await postJSON(`${API}/gold`, { alias: goldAlias, criteria: approvedFacts, goldSummary, goldNoteAlias })
      setGold(approvedFacts)
      setGoldDecisions(Object.fromEntries(approvedFacts.map((c) => [c.id, 'include' as GoldDecision])))
      setGoldWizardIndex(0)
      setGoldRevision(result.gold.revision); setGoldDirty(false)
      setNotice(`Gold set saved: ${approvedFacts.length} approved important facts. Each NEW benchmark run freezes this inventory.`)
    } catch (e) { setError(String(e)) }
    finally { setGoldSaving(false) }
  }
  const start = async () => {
    setStarting(true); setError(''); setNotice('')
    try {
      const roles = mode === 'both' ? ['local', 'frontier'] : [mode]
      const data = await postJSON(API, { aliases: chosen, maxTokens, roles, acknowledgeExternal: externalConsent })
      setSelected(data.runId); setReport({ state: 'starting' }); setNotice('Benchmark running independently; results are saved even if the browser closes.')
      void loadLedger()
    } catch (e) { setError(String(e)) }
    finally { setStarting(false) }
  }
  const saveReview = async () => {
    setSavingReview(true); setError('')
    try {
      await postJSON(`${API}/review`, { runId: selected, alias: comparisonAlias, role: reviewRole,
        name: attemptName, grades: draftGrades, summaryGrades, claims: candidateClaims, notes: reviewNotes })
      await loadRun(selected); await loadLedger(); setNotice('Human assessment saved to the run ledger.')
    } catch (e) { setError(String(e)) }
    finally { setSavingReview(false) }
  }
  const updateCandidateClaim = (index: number, changes: Partial<ClaimReview>) =>
    setCandidateClaims((rows) => rows.map((row, i) => i === index ? { ...row, ...changes } : row))
  const currentMetrics = scoreSummaryFacts(goldForReview, { grades: draftGrades, claims: candidateClaims })
  const ledgerRows = runs.flatMap((r) => (['local','frontier'] as const)
    .filter(role => (ledgerModel === 'all' || ledgerModel === role) && (r.roles || ['local']).includes(role))
    .map(role => ({ run: r, role, metrics: r.factual_metrics?.[role] })))
  const pendingChartRows = ledgerRows.filter(row => row.metrics?.status !== 'scored')
  const chartRows = [...ledgerRows].filter(row => row.metrics?.status === 'scored')
    .sort((a,b) => `${a.run.started_at || ''}-${a.run.id}-${a.role}`.localeCompare(`${b.run.started_at || ''}-${b.run.id}-${b.role}`))
  const updateGold = (index: number, changes: Partial<Criterion>) => {
    const previousId = gold[index]?.id
    if (previousId) setGoldDecisions((old) => {
      const next = { ...old }
      delete next[previousId] // Edited fact must be re-approved, including ID-only edits.
      return next
    })
    setGold((old) => old.map((c, i) => i === index ? { ...c, ...changes } : c)); setGoldDirty(true)
  }
  const goldIncluded = gold.filter((f) => goldDecisions[f.id] === 'include').length
  const goldExcluded = gold.filter((f) => goldDecisions[f.id] === 'exclude').length
  const goldPending = gold.length - goldIncluded - goldExcluded
  const visibleGold = gold.filter((f) => !goldPendingOnly || !goldDecisions[f.id])
  const safeWizardIndex = Math.min(goldWizardIndex, Math.max(visibleGold.length - 1, 0))
  const wizardFact = visibleGold[safeWizardIndex]
  const decisionFor = (fact: Criterion, decision: GoldDecision | null) => {
    setGoldDecisions((old) => {
      const next = { ...old }
      if (decision) next[fact.id] = decision
      else delete next[fact.id]
      return next
    })
    setGoldDirty(true)
    // In the 'unreviewed only' view, a decision removes the current item.
    if (!goldPendingOnly && safeWizardIndex < visibleGold.length - 1) setGoldWizardIndex(safeWizardIndex + 1)
  }
  const addGoldFact = () => {
    if (gold.length >= 40) return
    const used = new Set(gold.map((f) => f.id))
    let next = 1
    while (used.has(`fact${next}`)) next++
    setGold((old) => [...old, { id: `fact${next}`, expectation: '' }])
    setGoldWizardIndex(goldPendingOnly ? visibleGold.length : gold.length)
    setGoldDirty(true)
  }
  const loadPasGold = () => {
    setGold(PAS_GOLD.map((f) => ({ ...f })))
    setGoldDecisions({}) // Suggestions are drafts, not silently approved.
    setGoldPendingOnly(true)
    setGoldWizardIndex(0)
    setGoldDirty(true)
  }

  return <div>
    <Card className='mb-3'><Card.Body>
      <h2 className='h4'>Select original HedgeDoc source notes</h2>
      <p className='text-muted'>Select 1–3 sources from the current Memex index, or none to use the fixed PAS 9980 page 48 fixture.
        Tests A (baseline), B (complete), C (three repeats) use the identical frozen source text for both providers.</p>
      <Alert variant='warning'>Memex queue processing must remain paused. Frontier runs <strong>send the selected original source text to an external API</strong>
        and may incur charges. No canonical notes, wiki, trails, queue or associations are modified.</Alert>
      <Form.Control aria-label='Find HedgeDoc sources' placeholder='Search title or alias' value={query} onChange={(e) => setQuery(e.target.value)} className='mb-2' />
      <div className='d-flex flex-wrap gap-2 align-items-center mb-2'>
        <Badge bg='secondary'>{chosen.length}/{MAX} selected</Badge>
        <Button size='sm' variant='outline-secondary' onClick={() => setChosen([])}>Use PAS 64 fixture</Button>
        <Button size='sm' variant='outline-secondary' onClick={() => void loadSources()}>Refresh sources</Button>
        <span className='small text-muted'>{sources.length} registered sources; up to 60 shown</span>
      </div>
      <div className='mb-2' style={{ maxHeight: 180, overflow: 'auto', padding: 8, border: '1px solid #8885' }}>
        {sourceLoading ? <Spinner animation='border' size='sm' /> : visibleSources.map((source) =>
          <Form.Check key={source.alias} type='checkbox' id={`bench-${source.alias}`} label={`${source.title} — ${source.alias}`}
            checked={chosen.includes(source.alias)} disabled={!chosen.includes(source.alias) && chosen.length >= MAX}
            onChange={() => toggle(source.alias)} />)}
      </div>
      <strong>Evaluation sources:</strong> {aliases.join(', ')}
    </Card.Body></Card>

    <Card className='mb-3'><Card.Body>
      <div className='d-flex justify-content-between align-items-center mb-2'>
        <h2 className='h4 mb-0'>Gold review — synthesized reference summary</h2>
        <Badge bg={goldDirty ? 'warning' : goldRevision ? 'success' : 'secondary'}>{goldDirty ? 'Unsaved changes' : goldRevision ? 'Saved' : 'Not saved'}</Badge>
      </div>
      <p className='text-muted'>Choose a source, then import a separate, human-authored HedgeDoc <strong>Gold Summary</strong> by its alias.
        Review the synthesis of the complete selected source (not extracted quotations), then save it as the versioned Gold Set.
        Each new run freezes the Gold Summary. Atomic Gold facts are required for factual precision/recall/F1-style scoring; a prose Gold Summary alone cannot define recall.</p>
      <Form.Group className='mb-2'><Form.Label>Gold source</Form.Label>
        <Form.Select aria-label='Gold source' value={goldAlias} onChange={(e) => setGoldAlias(e.target.value)}>
          {aliases.map((a) => <option key={a} value={a}>{sources.find((s) => s.alias === a)?.title || a}</option>)}
        </Form.Select>
      </Form.Group>
      {goldAlias !== FIXTURE && <p><a href={`/n/${encodeURIComponent(goldAlias)}`} target='_blank' rel='noopener noreferrer'>Open original HedgeDoc source for gold review ↗</a></p>}
      <Form.Group className='mb-2'>
        <Form.Label>HedgeDoc Gold Summary alias (separate from original source alias)</Form.Label>
        <div className='d-flex gap-2'>
          <Form.Control value={goldNoteQuery} onChange={(e) => setGoldNoteQuery(e.target.value)}
            aria-label='HedgeDoc Gold note alias' placeholder='memex-gold-your-reference-summary' />
          <Button variant='outline-primary' size='sm' disabled={goldNoteLoading || !goldNoteQuery.trim()}
            onClick={() => void loadGoldFromNote()}>{goldNoteLoading ? 'Loading…' : 'Load from HedgeDoc'}</Button>
        </div>
        <Form.Text>Gold aliases start with <code>memex-gold-</code> and use standard <code>document / Concept</code> YAML.
          Import only previews the note; <strong>Save Gold Set</strong> is required to approve it.</Form.Text>
      </Form.Group>
      {goldNoteAlias && <p className='small'>Reference note: <a target='_blank' rel='noopener noreferrer'
        href={`/n/${encodeURIComponent(goldNoteAlias)}`}>{goldNoteAlias} ↗</a></p>}
      <Form.Group className='mb-2'><Form.Label>Human-approved Gold Reference Summary (entire selected document)</Form.Label>
        <Form.Control as='textarea' rows={13} value={goldSummary} aria-label='Gold Reference Summary'
          onChange={(e) => { setGoldSummary(e.target.value); setGoldDirty(true) }}
          placeholder='A synthesized, factual and comprehensive summary of the whole selected HedgeDoc source (200–20,000 characters).' />
        <Form.Text>{goldSummary.trim().length} characters. This text—not the original source note—is frozen as the reference summary.</Form.Text>
      </Form.Group>
      <div className='border rounded p-3 mb-2' aria-label='Gold fact review wizard'>
        <div className='d-flex flex-wrap justify-content-between align-items-center gap-2 mb-2'>
          <h3 className='h5 mb-0'>Gold review — source fact wizard</h3>
          <span className={`badge bg-${goldPending ? 'warning text-dark' : goldIncluded ? 'success' : 'secondary'}`}>
            {gold.length - goldPending}/{gold.length} labeled {goldDirty ? '· Unsaved' : ''}
          </span>
        </div>
        <p className='small text-muted'>As in Association Gold Review: verify each proposed important source fact against the
          <strong> original source</strong>, then Include or Exclude. A Gold Summary is helpful context but not proof.
          Excluded/unreviewed suggestions never enter a frozen Gold Set.</p>
        <div className='d-flex flex-wrap align-items-center gap-2 mb-2'>
          <Form.Check type='checkbox' id='summary-gold-pending-only' label='Show only unreviewed' checked={goldPendingOnly}
            onChange={(e) => { setGoldPendingOnly(e.target.checked); setGoldWizardIndex(0) }} />
          <Button size='sm' variant='outline-primary' onClick={addGoldFact} disabled={gold.length >= 40}>Add expected fact</Button>
          {goldAlias === FIXTURE && <Button size='sm' variant='outline-secondary' onClick={loadPasGold}>Load PAS 64 suggested facts</Button>}
        </div>
        <div className='small mb-2'><strong>{goldIncluded} included</strong> · {goldExcluded} excluded · {goldPending} to review.
          {gold.length > 0 && goldPending === 0 ? ' All draft facts are labeled.' : ''}
        </div>
        {wizardFact ? <div className='border rounded p-3 mb-2'>
          <div className='d-flex justify-content-between gap-3 mb-2'>
            <span>Fact {safeWizardIndex + 1} of {visibleGold.length}</span>
            <span className='d-flex gap-2'>
              <Button size='sm' variant='outline-secondary' disabled={safeWizardIndex === 0}
                onClick={() => setGoldWizardIndex(Math.max(0, safeWizardIndex - 1))}>Previous</Button>
              <Button size='sm' variant='outline-secondary' disabled={safeWizardIndex >= visibleGold.length - 1}
                onClick={() => setGoldWizardIndex(Math.min(visibleGold.length - 1, safeWizardIndex + 1))}>Next</Button>
            </span>
          </div>
          <div className='d-flex flex-wrap gap-2 mb-2'>
            <Form.Control aria-label='Current Gold fact ID' style={{ flex: '0 1 170px' }} placeholder='Fact ID'
              value={wizardFact.id} onChange={(e) => updateGold(gold.indexOf(wizardFact), { id: e.target.value })} />
            <Form.Control aria-label='Current Gold fact expectation' style={{ flex: '1 1 370px' }}
              value={wizardFact.expectation} onChange={(e) => updateGold(gold.indexOf(wizardFact), { expectation: e.target.value })}
              placeholder='Atomic important source fact (check source, qualifiers, and scope)' />
          </div>
          <div className='d-flex flex-wrap gap-2 align-items-center'>
            <Button size='sm' variant={goldDecisions[wizardFact.id] === 'include' ? 'success' : 'outline-success'}
              disabled={!/^[A-Za-z0-9_-]{1,36}$/.test(wizardFact.id) || wizardFact.expectation.trim().length < 8}
              onClick={() => decisionFor(wizardFact, 'include')}>Include (verified)</Button>
            <Button size='sm' variant={goldDecisions[wizardFact.id] === 'exclude' ? 'danger' : 'outline-danger'}
              onClick={() => decisionFor(wizardFact, 'exclude')}>Exclude</Button>
            <Button size='sm' variant='outline-secondary' onClick={() => decisionFor(wizardFact, null)}>Clear label</Button>
            <span className='small text-muted'>{goldDecisions[wizardFact.id] || 'Unreviewed'}</span>
          </div>
        </div> : <Alert variant={gold.length && !goldPending ? 'success' : 'secondary'} className='mb-2'>
          {gold.length && !goldPending ? 'All source facts reviewed. Uncheck “Show only unreviewed” to revisit a decision.'
            : 'No draft facts. Add an expected source fact, or load the PAS 64 suggestions.'}</Alert>}
        <details className='mb-3'><summary>Advanced: view/edit all {gold.length} draft facts</summary>
          <div className='mt-2'>
          {gold.map((criterion, index) => <div key={`${index}`} className='d-flex flex-wrap gap-2 mb-2 align-items-center'>
            <Form.Control style={{ flex: '0 1 135px' }} aria-label={`Criterion ${index + 1} ID`} value={criterion.id}
              onChange={(e) => updateGold(index, { id: e.target.value })} placeholder='ID' />
            <Form.Control style={{ flex: '1 1 330px' }} aria-label={`Criterion ${index + 1} expected fact`} value={criterion.expectation}
              onChange={(e) => updateGold(index, { expectation: e.target.value })} placeholder='Expected source fact' />
            <Badge bg={goldDecisions[criterion.id] === 'include' ? 'success' : goldDecisions[criterion.id] === 'exclude' ? 'danger' : 'secondary'}>
              {goldDecisions[criterion.id] || 'Unreviewed'}</Badge>
            <Button variant='outline-danger' size='sm' onClick={() => {
              setGold((old) => old.filter((_, i) => i !== index))
              setGoldDecisions((old) => { const next = { ...old }; delete next[criterion.id]; return next })
              setGoldWizardIndex(0); setGoldDirty(true)
            }}>Remove</Button>
          </div>)}
          </div>
        </details>
        {goldPending > 0 && <Alert variant='warning' className='small'>Review {goldPending} remaining source fact(s) before saving.
          Decisions are draft-only until Save Gold Set is clicked.</Alert>}
        {!goldPending && !goldIncluded && <Alert variant='warning' className='small'>A Gold Summary without approved source facts can be saved, but it cannot generate factual P/R/F1 scores.</Alert>}
        <Button size='sm' onClick={() => void saveGold()}
          disabled={goldSaving || goldPending > 0 || gold.length > 40 ||
            (gold.length ? goldIncluded === 0 : goldSummary.trim().length < 200)}>
          {goldSaving ? 'Saving…' : `Save Gold Set (${goldIncluded} included)`}</Button>
      </div>
      <p className='small text-muted mt-2 mb-0'>Save is an explicit human approval; no Gold Summary is automatically generated from the source.
        Model quality is human-rated against the saved reference and not calculated by matching wording.</p>
    </Card.Body></Card>

    <Card className='mb-3'><Card.Body>
      <h2 className='h4'>Run benchmark — local vs frontier</h2>
      <div className='d-flex flex-wrap gap-3 align-items-end mb-2'>
        <Form.Group><Form.Label>Models</Form.Label>
          <Form.Select value={mode} onChange={(e) => setMode(e.target.value as 'local' | 'frontier' | 'both')}>
            <option value='local'>Local Gemma4</option>
            <option value='frontier' disabled={!frontier.available}>Frontier only</option>
            <option value='both' disabled={!frontier.available}>Local + frontier (paired)</option>
          </Form.Select>
        </Form.Group>
        <Form.Group><Form.Label>Maximum output tokens</Form.Label>
          <Form.Select value={maxTokens} onChange={(e) => setMaxTokens(Number(e.target.value))}>
            <option value={1024}>1024</option><option value={2048}>2048</option><option value={4096}>4096</option>
          </Form.Select>
        </Form.Group>
        <Button disabled={starting || sourceLoading || (mode !== 'local' && (!frontier.available || !externalConsent))}
          onClick={() => void start()}>{starting ? 'Starting…' : `Run A/B/C — ${aliases.length * 5 * (mode === 'both' ? 2 : 1)} calls`}</Button>
      </div>
      <div className='small mb-2'>{frontier.available ? `Frontier configured: ${frontier.model}` : 'Frontier not configured: see .env.memex-benchmark example in deployment ZIP.'}</div>
      {mode !== 'local' && <Form.Check type='checkbox' checked={externalConsent} onChange={(e) => setExternalConsent(e.target.checked)}
        label='I authorize sending the selected original HedgeDoc source text to the configured external frontier model and accept API charges.' />}
      <p className='small text-muted mt-2'>Both models receive the same source snapshot, identical prompts and output-token budget.
        Local inference accepts seeds. Frontier defaults to provider sampling controls unless explicitly configured; repeats and scores must be interpreted with that limitation.</p>
    </Card.Body></Card>

    {error && <Alert variant='danger'>{error}</Alert>}
    {notice && <Alert variant='info'>{notice}</Alert>}
    <Card className='mb-3'><Card.Body>
      <div className='d-flex flex-wrap align-items-end gap-3 mb-3'>
        <Form.Group><Form.Label>Model filter</Form.Label>
          <Form.Select aria-label='Ledger model filter' value={ledgerModel} onChange={(e) => setLedgerModel(e.target.value as 'all'|'local'|'frontier')}>
            <option value='all'>All models</option><option value='local'>Local Gemma4</option><option value='frontier'>Frontier model</option>
          </Form.Select>
        </Form.Group>
        <Button size='sm' variant='outline-secondary' onClick={() => void loadLedger()}>Refresh metrics</Button>
        <span className='small text-muted'>{chartRows.length} fully reviewed model/run scores; {pendingChartRows.length} pending (no invented scores).</span>
      </div>
      <h2 className='h4'>Quality trend</h2>
      <p className='small text-muted'>As in Association Benchmarks: solid factual precision, dashed information recall, dotted F1-style. Scores use reviewed atomic claims/frozen source facts, never keyword matching.</p>
      {chartRows.length ? <div style={{ overflowX: 'auto' }}><svg role='img' aria-label='Summary factual precision recall and F1-style trend' viewBox='0 0 920 300' style={{ minWidth: 720, width: '100%' }}>
        {[0, .25, .5, .75, 1].map(t => <g key={t}><line x1='58' x2='902' y1={20 + (1-t)*226} y2={20 + (1-t)*226} stroke='currentColor' opacity='.16'/><text x='8' y={24 + (1-t)*226} fontSize='12' fill='currentColor'>{Math.round(t*100)}%</text></g>)}
        {(['precision','recall','f1_style'] as const).map((key, index) => <polyline key={key} fill='none' stroke={index === 0 ? '#0d6efd' : index === 1 ? '#198754' : '#dc3545'} strokeWidth={index === 0 ? 3 : 2.5} strokeDasharray={index === 0 ? undefined : index === 1 ? '8 5' : '2 5'}
          points={chartRows.map((row,i) => `${58 + (chartRows.length < 2 ? 422 : 844*i/(chartRows.length-1))},${20 + (1-(row.metrics?.[key] ?? 0))*226}`).join(' ')}/>)}
        {chartRows.map((row,i) => <text key={`${row.run.id}-${row.role}`} fontSize='10' fill='currentColor' textAnchor='end'
          transform={`translate(${58 + (chartRows.length < 2 ? 422 : 844*i/(chartRows.length-1))} 286) rotate(-35)`}>{row.run.id.slice(0,6)} {row.role}</text>)}
      </svg><div className='small'>Solid blue: factual precision · dashed green: information recall · dotted red: F1-style</div></div>
        : <div style={{overflowX:'auto'}}><svg role='img' aria-label='Quality trend awaiting reviewed metrics; no scores plotted' viewBox='0 0 920 300' style={{minWidth:720,width:'100%'}}>
          {[0,.25,.5,.75,1].map(t=><g key={t}><line x1='58' x2='902' y1={20+(1-t)*226} y2={20+(1-t)*226} stroke='currentColor' opacity='.16'/>
            <text x='8' y={24+(1-t)*226} fill='currentColor' fontSize='12'>{Math.round(t*100)}%</text></g>)}
          <text x='480' y='135' textAnchor='middle' fontSize='16' fill='currentColor'>Awaiting source-grounded human review</text>
          <text x='480' y='156' textAnchor='middle' fontSize='12' fill='currentColor'>No Precision / Recall / F1-style values are inferred from unreviewed model output.</text>
          {pendingChartRows.slice(0,10).map((row,i)=><g key={`${row.run.id}-${row.role}`}>
            <circle cx={70+i*90} cy='270' r='5' fill='#888'/>
            <text x={70+i*90} y='290' textAnchor='middle' fontSize='10' fill='currentColor'>{row.run.id.slice(0,6)}</text>
          </g>)}
        </svg><p className='small text-muted'>Graph scaffold matches Association Benchmarks; grey run markers mean pending verification, <strong>not zero accuracy</strong>.</p></div>}
      {!!pendingChartRows.length && <div className='mt-2 small'><strong>Runs pending human verification:</strong>{' '}
        {pendingChartRows.slice(0, 12).map(x => `${x.run.id.slice(0, 8)} (${x.role})`).join(', ')}
        {pendingChartRows.length > 12 ? ` + ${pendingChartRows.length - 12} more` : ''}.</div>}
    </Card.Body></Card>
    <Card className='mb-3'><Card.Body>
      <h2 className='h4'>Run ledger</h2>
      <p className='small text-muted'>Same ledger structure as Association Benchmarks, with source-grounded summary metrics. F1-style combines supported-claim precision and important-fact recall (different denominators); FP is unsupported/contradicted claims, FN is uncovered important facts. These counts are diagnostic, not classical decision confusion-matrix scores.</p>
      <Table size='sm' bordered hover responsive><thead><tr>
        <th>Run</th><th>Model</th><th>Scope</th><th>Factual Precision</th><th>Information Recall</th><th>F1-style</th><th>FP*</th><th>FN*</th><th>Pairs</th><th>Runtime</th>
      </tr></thead><tbody>
      {ledgerRows.map(({run:r,role,metrics}) => <tr key={`${r.id}-${role}`} onClick={() => {setReviewRole(role);setSelected(r.id);setReport(undefined)}} style={{cursor:'pointer'}}>
        <td title={r.started_at || ''}><code>{r.id.slice(0,8)}</code></td>
        <td>{r.providers?.[role]?.model || (role === 'local' ? r.model || 'Local' : 'Frontier')}</td>
        <td>{(r.source_titles?.length || 0)} source(s), A/B/C</td>
        <td>{metrics?.status === 'scored' ? `${(100*(metrics.precision || 0)).toFixed(1)}%` : '—'}</td>
        <td>{metrics?.status === 'scored' ? `${(100*(metrics.recall || 0)).toFixed(1)}%` : '—'}</td>
        <td>{metrics?.status === 'scored' ? `${(100*(metrics.f1_style || 0)).toFixed(1)}%` : '—'}</td>
        <td>{metrics?.status === 'scored' ? metrics.unsupported + metrics.contradicted : '—'}</td>
        <td>{metrics?.status === 'scored' ? metrics.missing : '—'}</td>
        <td title={metrics?.reason || 'Pending review'}>{metrics?.completed_attempts ?? 0}/{metrics?.total_attempts ?? (r.role_attempts?.[role] ?? 0)} {metrics?.status !== 'scored' ? '· pending' : ''}</td>
        <td>{r.role_seconds?.[role] === undefined ? '—' : `${r.role_seconds[role]}s`}</td>
      </tr>)}
      {!ledgerRows.length && <tr><td colSpan={10}>No summary-quality runs recorded yet.</td></tr>}
      </tbody></Table>
      <div className='small text-muted'>Click a ledger row for Association-style Pair results, outcomes and network; then verify decisions. Unresolved/partial assessments never produce a final score.</div>
    </Card.Body></Card>

    {selected && <Card className='mb-3'><Card.Body>
      <h2 className='h4'>Detailed results — {selected.slice(0, 8)}</h2>
      <Badge bg={report?.status === 'completed' ? 'success' : 'secondary'}>{report?.status || report?.state || 'loading'}</Badge>{' '}
      <span className='small text-muted'>{Object.entries(report?.providers || {}).map(([r, p]) => `${r}: ${p.model}`).join(' · ')}</span>
      <div className='d-flex gap-3 my-3 flex-wrap'>
        <Form.Group><Form.Label>Source</Form.Label><Form.Select value={comparisonAlias} onChange={(e) => setComparisonAlias(e.target.value)}>
          {(report?.sources || []).map((src) => <option key={src.alias} value={src.alias}>{src.title}</option>)}
        </Form.Select></Form.Group>
        <Form.Group><Form.Label>Prompt</Form.Label><Form.Select value={attemptName} onChange={(e) => setAttemptName(e.target.value)}>
          {TESTS.map((name) => <option key={name} value={name}>{name}</option>)}
        </Form.Select></Form.Group>
      </div>
      <p className='small'>Frozen source SHA-256: <code>{report?.sources?.find((s) => s.alias === comparisonAlias)?.sha256 || '—'}</code>.
        Gold: <code>{report?.gold?.[comparisonAlias]?.revision || 'not saved at run start'}</code>.</p>
      <div className='border rounded p-3 mb-3'>
        <h3 className='h5'>Run Gold-fact Outcome evaluation (one direct model call)</h3>
        <p className='small text-muted'>As in Association Benchmarks, ask the shared-configured LOCAL model for one direct decision per frozen Gold fact, using the saved summary (SHA-256 checked).
          This does <strong>not</strong> rerun A/B/C or modify the wiki. The local model may be judging its own output;
          decisions are <strong>PROVISIONAL</strong> until a person verifies them.</p>
        <div className='d-flex flex-wrap gap-2 align-items-center'>
          <Button size='sm' variant='outline-primary' onClick={() => void evaluateSaved()}
            disabled={evaluating || !compared(reviewRole) || compared(reviewRole)?.status !== 'completed'}>
            {evaluating ? 'Starting…' : 'Evaluate saved output (provisional)'}</Button>
          <span className='small'>Evaluation: {provisionalFor === evalKey ?
            `${provisional.status}${provisional.stage ? ' · ' + provisional.stage : ''}` : 'not loaded'}</span>
          {activeProvisional && <Button size='sm' variant='outline-secondary' onClick={draftFromProposal}>
            Copy proposals into human review</Button>}
        </div>
        {provisionalFor === evalKey && provisional.status === 'failed' && <Alert variant='danger' className='mt-2 mb-0'>{provisional.error}</Alert>}
        {activeProvisional && <Alert variant='warning' className='mt-2 mb-0'>
          <strong>PROVISIONAL / LOCAL JUDGE</strong> — {activeProvisional.judge_model || 'unknown model'}.
          {activeProvisional.scores?.status === 'provisional'
            ? ` Preliminary factual P ${(100 * (activeProvisional.scores.precision || 0)).toFixed(1)}%, R ${(100 * (activeProvisional.scores.recall || 0)).toFixed(1)}%, F1-style ${(100 * (activeProvisional.scores.f1_style || 0)).toFixed(1)}%.`
            : ` ${activeProvisional.scores?.reason || 'Awaiting adjudication'}.`}
          {' '}Unreviewed scores never enter the verified Run Ledger / Quality Trend.
        </Alert>}
      </div>
      <div className='d-flex flex-wrap align-items-end justify-content-between gap-3 mb-3'>
        <h2 className='h4 mb-0'>Pair results</h2>
        <Form.Group style={{minWidth:'200px'}}><Form.Label>Outcome</Form.Label>
          <Form.Select aria-label='Pair results outcome' value={resultOutcome} onChange={e=>setResultOutcome(e.target.value)}>
            <option value='all'>All outcomes</option><option value='covered'>True positive</option>
            <option value='missing'>False negative</option><option value='incorrect'>Contradiction</option>
            <option value='unrated'>Unreviewed / uncertain</option>
          </Form.Select>
        </Form.Group>
      </div>
      <p className='small text-muted'>Same decision table as Association Benchmarks. Source A = frozen Gold fact;
        Source B = actual saved model summary (not an invented quote or location). Predictions are provisional
        until human-approved. No fake confidence or unverified Precision/F1-style.</p>
      <div style={{ overflowX:'auto', maxHeight:'520px' }}>
        <Table bordered hover responsive size='sm'>
          <thead><tr><th>Source A</th><th>Source B</th><th>Gold</th><th>Prediction</th><th>Confidence</th><th>Outcome</th><th>Reason</th></tr></thead>
          <tbody>
            {goldForReview.map(f => {
              const grade = tableReview?.grades?.[f.id] || 'unrated'
              const outcome = grade === 'covered' ? 'True positive' : grade === 'missing' ? 'False negative' :
                grade === 'incorrect' ? 'Contradiction' : 'Unreviewed / uncertain'
              const variant = grade === 'covered' ? 'success' : grade === 'missing' ? 'warning' :
                grade === 'incorrect' ? 'danger' : 'secondary'
              if (resultOutcome !== 'all' && !(resultOutcome === 'covered' && grade === 'covered') &&
                !(resultOutcome === 'missing' && grade === 'missing') &&
                !(resultOutcome === 'incorrect' && grade === 'incorrect') &&
                !(resultOutcome === 'unrated' && !['covered','missing','incorrect'].includes(grade))) return null
              const linked = (tableReview?.claims || []).filter(c => c.matched_fact_ids?.includes(f.id))
              return <tr key={`gold-${f.id}`}>
                <td><strong>{f.id}</strong> — {f.expectation}</td>
                <td>{linked.length ? linked.map(c => `${c.id}: ${c.text}`).join(' · ') :
                  `${comparisonAlias} · ${reviewRole} · ${attemptName} (saved model summary)`}</td>
                <td>Required fact</td><td>{grade === 'covered' ? 'Covered' : grade === 'missing' ? 'Missing' :
                  grade === 'incorrect' ? 'Incorrect' : grade === 'partial' ? 'Partial — needs review' : 'Unreviewed'}</td>
                <td>—</td>
                <td><Badge bg={variant}>{outcome}{provisionalOnly ? ' · PROVISIONAL' : ''}</Badge></td>
                <td style={{minWidth:'320px'}}>{provisionalOnly ?
                  activeProvisional?.fact_reasons?.[f.id] || 'Provisional; awaiting verification' :
                  savedReview?.notes || 'Human semantic coverage assessment (see editor)'}</td>
              </tr>
            })}
            {(tableReview?.claims || []).map(c => {
              const outcome = c.verdict === 'supported' ? 'Supported' : c.verdict === 'not_in_source' ?
                'Unsupported claim' : c.verdict === 'contradicted' ? 'Contradiction' : 'Unreviewed / uncertain'
              if (resultOutcome !== 'all' && !outcome.toLowerCase().includes(resultOutcome) &&
                !(resultOutcome === 'covered' && c.verdict === 'supported') &&
                !(resultOutcome === 'missing' && c.verdict === 'not_in_source') &&
                !(resultOutcome === 'incorrect' && c.verdict === 'contradicted') &&
                !(resultOutcome === 'unrated' && ['unrated','uncertain'].includes(c.verdict))) return null
              return <tr key={`claim-${c.id}`}><td>{c.matched_fact_ids?.length ? `Gold: ${c.matched_fact_ids.join(', ')}` : `${comparisonAlias} (original source)`}</td>
                <td><strong>{c.id}</strong> — {c.text}</td><td>Source support</td><td>Claim asserted</td>
                <td>{c.confidence == null ? '—' : `${(c.confidence*100).toFixed(0)}% (reviewer)`}</td>
                <td><Badge bg={c.verdict === 'supported' ? 'success' : c.verdict === 'unrated' || c.verdict === 'uncertain' ? 'secondary' : 'danger'}>{outcome}</Badge></td>
                <td style={{minWidth:'320px'}}>{c.reason || c.evidence || 'No reviewer evidence'}</td></tr>
            })}
            {!goldForReview.length && !(tableReview?.claims?.length) &&
              <tr><td colSpan={7}>No frozen Gold facts. Save Gold and select a benchmark run.</td></tr>}
          </tbody>
        </Table>
      </div>
      <h2 className='h4 mt-4'>Gold fact ↔ model summary network</h2>
      <SummaryFactNetwork facts={goldForReview} claims={tableReview?.claims || []}
        grades={tableReview?.grades || {}} source={comparisonAlias} model={reviewRole} prompt={attemptName}
        saved={!!savedReview} provisional={provisionalOnly} />
      <div className='row'>
        {(['local', 'frontier'] as const).map((role) => {
          const a = compared(role)
          return <div className='col-12 col-lg-6 mb-3' key={role}>
            <h3 className='h5'>{role === 'local' ? 'Local model' : 'Frontier model'} — {a?.model || 'not run'}</h3>
            {a ? <>
              <div className='small'>Status: {a.status}; duration: {a.duration_seconds ?? '—'}s; finish: {a.finish_reason || '—'}
                {a.truncated ? ' (TRUNCATED)' : ''}</div>
              <pre style={{ whiteSpace: 'pre-wrap', overflow: 'auto', height: 360, border: '1px solid #ccc', padding: 12 }}>
                {a.output || a.error || 'Generating…'}</pre>
              {a.score?.coverage_total ? <div className='small text-muted'>PAS keyword proxy: {a.score.coverage_proxy}/{a.score.coverage_total}; manual review still required.</div> : null}
            </> : <Alert variant='secondary'>This provider/test is not part of the run or has not started.</Alert>}
          </div>
        })}
      </div>
      <h3 className='h5'>Human review — compare model output to frozen Gold Summary</h3>
      <p className='small'>Assess semantic completeness, factual accuracy, conditions and grounding. The reference is not a phrase-match target;
        paraphrases are valid. Each grade applies to the selected model and A/B/C attempt.</p>
      {summaryForReview && <details className='mb-3' open><summary>Frozen Gold Reference Summary — view</summary>
        <pre style={{ whiteSpace: 'pre-wrap', maxHeight: 310, overflow: 'auto', padding: 12, border: '1px solid #ccc' }}>
          {summaryForReview}</pre>
        {report?.gold?.[comparisonAlias]?.gold_note_alias && <div className='small'>HedgeDoc Gold alias:
          <code> {report?.gold?.[comparisonAlias]?.gold_note_alias}</code></div>}
      </details>}
      <Form.Select value={reviewRole} onChange={(e) => setReviewRole(e.target.value)} className='mb-2' aria-label='Model to review'>
        <option value='local'>Review local model</option><option value='frontier'>Review frontier model</option>
      </Form.Select>
      {summaryForReview && SUMMARY_DIMENSIONS.map((dimension) => <div key={dimension.id} className='d-flex align-items-center gap-3 mb-2'>
        <div style={{ flex: 1 }}><strong>{dimension.label}</strong></div>
        <Form.Select aria-label={`Grade ${dimension.id}`} style={{ maxWidth: 240 }}
          value={summaryGrades[dimension.id] || 'unrated'} onChange={(e) =>
            setSummaryGrades((old) => ({ ...old, [dimension.id]: e.target.value as Grade }))}>
          {LABELS.map((x) => <option value={x.value} key={x.value}>{x.label}</option>)}
        </Form.Select>
      </div>)}
      {goldForReview.length > 0 && <details className='mb-3'><summary>Optional factual expectation grades ({goldForReview.length})</summary>
      {goldForReview.map((item) => <div key={item.id} className='d-flex align-items-center gap-3 mb-2'>
        <div style={{ flex: 1 }}><strong>{item.id}</strong> — {item.expectation}</div>
        <Form.Select aria-label={`Grade ${item.id}`} style={{ maxWidth: 230 }} value={draftGrades[item.id] || 'unrated'}
          onChange={(e) => setDraftGrades((old) => ({ ...old, [item.id]: e.target.value as Grade }))}>
          {LABELS.map((x) => <option value={x.value} key={x.value}>{x.label}</option>)}
        </Form.Select>
      </div>)}
      </details>}
      <h3 className='h5 mt-4'>Atomic candidate claims — source-grounded precision</h3>
      <p className='small text-muted'>One distinct factual proposition per row, taken from the selected model output. Review against the <strong>original source</strong>, not just the Gold Summary. Record a source passage/section for supported claims, or a reason for unsupported/contradicted claims. Deduplicate paraphrases. Uncertain rows block scoring.</p>
      {candidateClaims.map((c,i) => <div className='border rounded p-2 mb-2' key={i}>
        <div className='d-flex flex-wrap gap-2 mb-2'>
          <Form.Control style={{maxWidth:100}} aria-label={`Claim ${i+1} ID`} value={c.id} onChange={e=>updateCandidateClaim(i,{id:e.target.value})}/>
          <Form.Control style={{flex:'1 1 320px'}} aria-label={`Claim ${i+1} proposition`} placeholder='One atomic claim, preserving qualifiers' value={c.text} onChange={e=>updateCandidateClaim(i,{text:e.target.value})}/>
          <Button size='sm' variant='outline-danger' onClick={()=>setCandidateClaims(rows=>rows.filter((_,j)=>j!==i))}>Remove</Button>
        </div>
        <div className='d-flex flex-wrap gap-2'>
          <Form.Select style={{flex:'1 1 220px'}} aria-label={`Claim ${i+1} verdict`} value={c.verdict} onChange={e=>updateCandidateClaim(i,{verdict:e.target.value as ClaimReview['verdict']})}>
            <option value='unrated'>Unrated</option><option value='supported'>Supported by source</option><option value='contradicted'>Contradicted</option>
            <option value='not_in_source'>Not in source (after full check)</option><option value='uncertain'>Uncertain — needs adjudication</option>
          </Form.Select>
          <Form.Control style={{flex:'2 1 250px'}} aria-label={`Claim ${i+1} evidence`} placeholder='Evidence: source page, section and excerpt' value={c.evidence} onChange={e=>updateCandidateClaim(i,{evidence:e.target.value})}/>
          <Form.Control style={{flex:'2 1 250px'}} aria-label={`Claim ${i+1} reason`} placeholder='Reason / qualification / contradiction' value={c.reason} onChange={e=>updateCandidateClaim(i,{reason:e.target.value})}/>
          <Form.Control style={{width:125}} aria-label={`Claim ${i+1} confidence`} placeholder='Confidence 0–1' type='number' min='0' max='1' step='.01'
            value={c.confidence ?? ''} onChange={e=>updateCandidateClaim(i,{confidence:e.target.value === '' ? null : Number(e.target.value)})}/>
        </div>
        {!!goldForReview.length && <details className='mt-2'><summary className='small'>Link claim to reviewed Gold fact(s) (optional; explicit evidence mapping)</summary>
          <div className='d-flex flex-wrap gap-3 mt-2'>
            {goldForReview.map(f => <Form.Check key={f.id} type='checkbox' id={`claim-${i}-fact-${f.id}`}
              label={`${f.id}: ${f.expectation}`} checked={!!c.matched_fact_ids?.includes(f.id)}
              onChange={e => updateCandidateClaim(i, { matched_fact_ids: e.target.checked
                ? [...(c.matched_fact_ids || []), f.id]
                : (c.matched_fact_ids || []).filter(id => id !== f.id) })} />)}
          </div>
        </details>}
      </div>)}
      <Button size='sm' variant='outline-primary' disabled={candidateClaims.length >= 120}
        onClick={()=>setCandidateClaims(rows=>[...rows,{id:`c${rows.length+1}`,text:'',verdict:'unrated',evidence:'',reason:'',confidence:null}])}>Add candidate claim</Button>
      <Alert className='mt-3' variant={currentMetrics.status==='scored'?'success':'warning'}>
        <strong>Factual P/R/F1-style: </strong>{currentMetrics.status === 'scored'
          ? `${percent(currentMetrics.supported,currentMetrics.claim_count)} precision · ${percent(currentMetrics.covered,currentMetrics.fact_count)} recall · ${((currentMetrics.f1_style||0)*100).toFixed(1)}% F1-style; ${currentMetrics.contradicted} contradicted claims`
          : `Not scored — ${currentMetrics.reason}`}. Grades and claims must be saved before the ledger/graph updates.
      </Alert>
      {(summaryForReview || goldForReview.length > 0) && <Form.Group className='mb-2'>
        <Form.Label>Reviewer notes: unsupported claims, omissions, or important differences</Form.Label>
        <Form.Control as='textarea' rows={3} maxLength={4000} value={reviewNotes} aria-label='Reviewer notes'
          onChange={(e) => setReviewNotes(e.target.value)} />
      </Form.Group>}
      {summaryForReview || goldForReview.length ? <Button size='sm' onClick={() => void saveReview()} disabled={savingReview || !compared(reviewRole) ||
        !['completed', 'truncated'].includes(compared(reviewRole)?.status || '')}>
        {savingReview ? 'Saving…' : 'Save human grades to ledger'}</Button> : <Alert variant='warning'>This run has no frozen Gold Set. Save Gold and start a new run.</Alert>}
      <div className='small mt-2'>Saved review: {savedReview?.reviewed_at || 'not yet reviewed'}</div>
      <h3 className='h5 mt-3'>All test attempts</h3>
      <Table size='sm' bordered responsive><thead><tr><th>Source</th><th>Model</th><th>Test</th><th>Status</th><th>Time</th><th>Finish</th></tr></thead><tbody>
        {(report?.attempts || []).map((a, i) => <tr key={i}>
          <td>{a.source_title}</td><td>{a.model_role || 'local'}</td><td>{a.name}</td><td>{a.status}</td>
          <td>{a.duration_seconds ?? '—'}s</td><td>{a.finish_reason || '—'}</td>
        </tr>)}
      </tbody></Table>
    </Card.Body></Card>}
  </div>
}
