/** Deterministic edges from a frozen Gold inventory and SAVED human review.
 * No evidence, match or prediction is inferred by this module. */
export type NetworkGold = { id: string; expectation: string }
export type NetworkClaim = {
  id: string; text: string; verdict: string; matched_fact_ids?: string[]
}
export type NetworkEdge = {
  key: string; from: string; to: string; status: string; kind: 'coverage' | 'claim' | 'explicit_match'
}

export function summaryNetworkEdges(
  gold: NetworkGold[], claims: NetworkClaim[], grades: Record<string, string> = {},
): NetworkEdge[] {
  const factIds = new Set(gold.map(f => f.id))
  const edges: NetworkEdge[] = [
    ...gold.map(f => ({ key: `gold:${f.id}`, from: `fact:${f.id}`, to: 'summary',
      status: grades[f.id] || 'unrated', kind: 'coverage' as const })),
    ...claims.map(c => ({ key: `claim:${c.id}`, from: 'summary', to: `claim:${c.id}`,
      status: c.verdict, kind: 'claim' as const })),
  ]
  for (const claim of claims) {
    const visited = new Set<string>()
    for (const id of claim.matched_fact_ids || []) {
      if (!factIds.has(id) || visited.has(id)) continue
      visited.add(id)
      edges.push({ key: `match:${id}:${claim.id}`, from: `fact:${id}`, to: `claim:${claim.id}`,
        status: 'human_linked', kind: 'explicit_match' })
    }
  }
  return edges
}
