'use client'

import React from 'react'
import { NetworkClaim, NetworkGold, NetworkEdge, summaryNetworkEdges } from './summary-network-data'

type Props = { facts: NetworkGold[]; claims: NetworkClaim[]; grades: Record<string, string>;
  source: string; model: string; prompt: string; saved: boolean; provisional?: boolean }

const EDGE_COLORS: Record<string, string> = {
  covered: '#198754', supported: '#198754', missing: '#dc3545', incorrect: '#dc3545',
  contradicted: '#dc3545', not_in_source: '#bd6113', partial: '#c38b19',
  uncertain: '#6c757d', unrated: '#9aa1a9', human_linked: '#1260a2',
}
function strokeFor(edge: NetworkEdge) { return EDGE_COLORS[edge.status] || '#9aa1a9' }
function dashFor(edge: NetworkEdge) {
  if (edge.status === 'covered' || edge.status === 'supported') return undefined
  if (edge.kind === 'explicit_match') return '3 4'
  return '7 5'
}
function short(label: string, limit = 43) { return label.length > limit ? label.slice(0, limit - 1) + '…' : label }

/** Association-style source-fact ↔ summary ↔ claim graph, never inventing claim-to-fact links. */
export function SummaryFactNetwork({ facts, claims, grades, source, model, prompt, saved, provisional }: Props) {
  const gold = facts.slice(0, 40)
  const asserted = claims.slice(0, 120)
  const rows = Math.max(gold.length, asserted.length, 3)
  const height = Math.max(310, 96 + rows * 43)
  const cy = height / 2
  const yFor = (index: number, total: number) => (height - Math.max(total - 1, 0) * 43) / 2 + index * 43
  const positions = new Map<string, [number, number]>([['summary', [570, cy]]])
  gold.forEach((f, i) => positions.set(`fact:${f.id}`, [220, yFor(i, gold.length)]))
  asserted.forEach((c, i) => positions.set(`claim:${c.id}`, [930, yFor(i, asserted.length)]))
  const edges = summaryNetworkEdges(gold, asserted, grades)
  const pairCount = edges.filter(e => e.kind === 'explicit_match').length
  return <div className='border rounded p-2 mt-3' aria-label='Summary fact network'>
    <h3 className='h5 mb-1'>Gold fact ↔ Model summary network</h3>
    <p className='small text-muted mb-2'>Association-style network for {source || 'selected source'} · {model} · {prompt}.
      Solid green = marked covered/supported; dashed red = marked missed/incorrect; grey = unreviewed.
      Thin blue dotted lines appear only for explicitly reviewed claim matches; direct Gold verdicts do not invent claim locations.
      {provisional ? ' PROVISIONAL LOCAL-JUDGE output; do not interpret as final accuracy.' :
        saved ? ' Displaying saved human reviews.' : ' No saved review for this attempt; edges are unreviewed.'}</p>
    <div style={{ overflowX: 'auto', maxHeight: 680, overflowY: 'auto' }}>
      <svg role='img' aria-label='Network of Gold source facts connected to the selected summary and its candidate claims' width='1140' height={height} viewBox={`0 0 1140 ${height}`}>
        <text x='100' y='25' fontSize='14' fontWeight='bold' fill='currentColor'>Frozen Gold facts ({gold.length})</text>
        <text x='480' y='25' fontSize='14' fontWeight='bold' fill='currentColor'>Model summary</text>
        <text x='805' y='25' fontSize='14' fontWeight='bold' fill='currentColor'>Reviewed atomic claims ({asserted.length})</text>
        {edges.map(e => {
          const a = positions.get(e.from)
          const b = positions.get(e.to)
          if (!a || !b) return null
          return <line key={e.key} x1={a[0]} y1={a[1]} x2={b[0]} y2={b[1]} stroke={strokeFor(e)}
            strokeWidth={e.kind === 'explicit_match' ? 1.3 : 2.4} strokeDasharray={dashFor(e)} opacity={e.kind === 'explicit_match' ? 0.8 : 0.65} />
        })}
        {gold.map((f, i) => {
          const y = yFor(i, gold.length)
          const grade = grades[f.id] || 'unrated'
          return <g key={`fact-${f.id}`}><title>{`${f.id}: ${f.expectation} — ${grade}`}</title>
            <circle cx='220' cy={y} r='8' fill={EDGE_COLORS[grade] || EDGE_COLORS.unrated} />
            <text x='205' y={y + 4} textAnchor='end' fontSize='12' fill='currentColor'>{short(f.id + ' · ' + f.expectation)}</text>
          </g>
        })}
        <g><title>{`${source} / ${model} / ${prompt}`}</title><circle cx='570' cy={cy} r='20' fill='#0d6efd' />
          <text x='570' y={cy + 39} textAnchor='middle' fontSize='12' fill='currentColor'>Model output</text></g>
        {asserted.map((c, i) => {
          const y = yFor(i, asserted.length)
          return <g key={`claim-${c.id}`}><title>{`${c.id}: ${c.text} — ${c.verdict}`}</title>
            <circle cx='930' cy={y} r='8' fill={EDGE_COLORS[c.verdict] || EDGE_COLORS.unrated} />
            <text x='944' y={y + 4} fontSize='12' fill='currentColor'>{short(c.id + ' · ' + c.text, 32)}</text>
          </g>
        })}
        {!gold.length && <text x='205' y={cy} textAnchor='end' fill='currentColor' fontSize='12'>No frozen Gold facts</text>}
        {!asserted.length && <text x='950' y={cy} fill='currentColor' fontSize='12'>No reviewed claims yet</text>}
      </svg>
    </div>
    <p className='small text-muted mt-2 mb-0'>{pairCount} explicit reviewed fact-to-claim links. Gold-fact verdicts draw only fact-to-summary lines; they do <strong>not</strong> assert specific claim evidence.
      Hover over nodes for complete text; unreviewed edges must not be interpreted as model failures.</p>
  </div>
}
